// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/api/absences", wrapper.ListAbsences)
	m.HandleFunc("POST "+options.BaseURL+"/api/absences", wrapper.CreateAbsence)
	m.HandleFunc("DELETE "+options.BaseURL+"/api/absences/{id}", wrapper.DeleteAbsence)
	m.HandleFunc("GET "+options.BaseURL+"/api/config", wrapper.GetConfig)
	m.HandleFunc("PUT "+options.BaseURL+"/api/config", wrapper.PutConfig)
	m.HandleFunc("GET "+options.BaseURL+"/api/entries", wrapper.ListEntries)
	m.HandleFunc("POST "+options.BaseURL+"/api/entries", wrapper.CreateEntry)
	m.HandleFunc("DELETE "+options.BaseURL+"/api/entries/{id}", wrapper.DeleteEntry)
	m.HandleFunc("PUT "+options.BaseURL+"/api/entries/{id}", wrapper.UpdateEntry)
	m.HandleFunc("GET "+options.BaseURL+"/api/holidays", wrapper.GetHolidays)
	m.HandleFunc("GET "+options.BaseURL+"/api/projects", wrapper.ListProjects)
	m.HandleFunc("POST "+options.BaseURL+"/api/projects", wrapper.CreateProject)
	m.HandleFunc("PUT "+options.BaseURL+"/api/projects/{id}", wrapper.UpdateProject)
	m.HandleFunc("GET "+options.BaseURL+"/api/report", wrapper.GetReport)
	m.HandleFunc("GET "+options.BaseURL+"/api/status", wrapper.GetStatus)
	m.HandleFunc("POST "+options.BaseURL+"/api/tracking/pause", wrapper.TrackingPause)
	m.HandleFunc("POST "+options.BaseURL+"/api/tracking/resume", wrapper.TrackingResume)
	m.HandleFunc("POST "+options.BaseURL+"/api/tracking/start", wrapper.TrackingStart)
	m.HandleFunc("POST "+options.BaseURL+"/api/tracking/stop", wrapper.TrackingStop)
	m.HandleFunc("POST "+options.BaseURL+"/api/tracking/switch", wrapper.TrackingSwitch)

	return m
}
